import type { EngineInterface, Register } from 'claude-code'

const HEADING = '## Session log'

/** Adds `line` at the end of the `## Session log` section, creating the section if missing. */
export function addLine(doc: string, line: string): string {
  const lines = doc.split('\n')
  const at = lines.findIndex(l => l.trim() === HEADING)
  if (at < 0) return `${doc.trimEnd() ? doc.trimEnd() + '\n\n' : ''}${HEADING}\n\n${line}\n`
  let end = at + 1
  while (end < lines.length && !/^#{1,2} /.test(lines[end] ?? '')) end++
  while (end > at + 1 && (lines[end - 1] ?? '').trim() === '') end--
  lines.splice(end, 0, line)
  return lines.join('\n')
}

/** The person's own prompts: user rows with text, no tool results, no injected tags. */
async function prompts($: EngineInterface): Promise<string[]> {
  const rows = await $.session.messages()
  return rows
    .filter(m => m.role === 'user' && !m.toolResults?.length)
    .map(m => m.text.trim())
    .filter(t => t && !t.startsWith('<'))
}

const oneLine = (s: string) => s.replace(/\s+/g, ' ').trim().slice(0, 140)

export const register: Register = (on, options) => {
  const path = String(options.trackerPath ?? '').trim()
  if (!path) return

  // session.end allows ~1.5 s in all, too little for a model call, so the
  // summary is refreshed after each main-thread turn and read at the end.
  let summary: string | undefined
  let seen: string[] = []

  on('turn.complete', ($, e, next) => {
    if (!e.agentId)
      void (async () => {
        const ps = (seen = await prompts($))
        if (!ps.length) return
        const r = await $.model.complete({
          model: 'haiku',
          effort: 'low',
          maxTokens: 60,
          timeoutMs: 30_000,
          prompt:
            'Summarize what this coding session was about in one short line (max 12 words, no quotes, no trailing period). The user prompts:\n\n' +
            ps.map(p => `- ${p.slice(0, 500)}`).join('\n'),
        })
        if (r.isAnswered && r.text.trim()) summary = oneLine(r.text)
      })().catch(() => {})
    return next(e)
  })

  on('session.end', async ($, e, next) => {
    // ponytail: some modes (claude -p) have no transcript at session.end; use the last turn's copy.
    const ps = await prompts($).catch(() => seen)
    if (ps.length) {
      const cwd = await $.session.cwd()
      const git = await $.process.run(['git', 'rev-parse', '--show-toplevel'], { cwd, timeoutMs: 500 })
      const root = (git.exitCode === 0 && git.stdout.trim()) || cwd
      const project = root.replace(/\/+$/, '').split('/').pop() || root
      const date = (await $.process.run(['date', '+%Y-%m-%d %H:%M'], { timeoutMs: 500 })).stdout.trim()
      const line = `- ${date} · ${project} · ${summary ?? oneLine(ps[0] ?? '')}`
      // Only a missing file starts empty; any other read error throws, so the file is never clobbered.
      const doc = (await $.fs.exists(path)) ? await $.fs.read(path) : ''
      await $.fs.write(path, addLine(doc, line))
    }
    summary = undefined
    seen = []
    return next(e)
  })
}

