{
  "name": "tracker-sync",
  "version": "0.1.0",
  "description": "When a session ends, appends a one-line log entry to a markdown tracker file (e.g. in an Obsidian vault).",
  "author": {
    "name": "AliakbarNateghi"
  },
  "userConfig": {
    "trackerPath": {
      "type": "string",
      "title": "Tracker file",
      "description": "Absolute path to the markdown file to log sessions in. Empty turns the mod off.",
      "default": ""
    }
  }
}
